var i=[{title:`Was Muskeln wachsen lässt`,text:`Muskeln wachsen als Antwort auf wiederholte mechanische Belastung und genug Erholung. Große Veränderungen dauern meist Monate oder Jahre, nicht ein paar Krafteinheiten. Stark zu sein und sehr muskulös auszusehen sind unterschiedliche Ergebnisse, und du kannst Trainingsziele wählen, die zu dem passen, was du willst.`},{title:`Was Vergleichsstudien zeigen`,text:`Eine Metaanalyse von 2025 fand, dass Frauen und Männer bei vergleichbaren Krafttrainingsprogrammen im Großen und Ganzen ähnliche relative Muskelgröße gewannen, wobei die absoluten Zuwächse der Männer im Durchschnitt etwas größer waren. Das ist kein Grund, Frauen vom Heben abzuraten. Es zeigt, dass Frauen echte Muskeln und Kraft aufbauen können.`},{title:`Für das trainieren, was du willst`,text:`Manche Menschen wollen sichtbares Muskelwachstum. Anderen sind Alltagskraft, Knochengesundheit, sportliche Leistung oder Selbstvertrauen wichtiger. Dein Trainingsumfang und deine Übungsauswahl können diesen Prioritäten folgen. Krafttraining verlangt keine Bodybuilding-Routinen oder jeden Tag schwerere Gewichte.`},{title:`Beispiel`,text:`Zwei Ganzkörpereinheiten pro Woche mit Kniebeugen, Rudern, Drücken und Hüftbeugen können Kraft und Funktion verbessern. Halte deine Leistung fest und mache dir keine Sorgen, dass ein einzelnes Training plötzlich verändert, wie du aussiehst.`},{title:`TrainUp nutzen`,text:`Im Profil wählst du dein Ziel: allgemeine Fitness, Kraft oder Kondition. Dein Plan wird aus diesem Ziel, deinem Level, deiner Ausrüstung und deinem Feedback zum Training aufgebaut und verspricht keine bestimmte Körperform.`}];var t=[{label:`Systematische Übersichtsarbeit von 2025: Muskelwachstum bei Männern und Frauen`,url:`https://pubmed.ncbi.nlm.nih.gov/40028215/`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:i,sources:t};export{s as default,i as sections,t as sources};